const table = () => ({ t: 'table', map: new Map(), header: false })
const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class Fail {
  constructor(msg) { this.confError = msg }
}
const fail = (m) => { throw new Fail(m) }

function walkTo(root, names, upto) {
  // descend through names[0..upto), creating tables; returns the table reached
  let cur = root
  for (let i = 0; i < upto; i++) {
    let nx = cur.map.get(names[i])
    if (nx === undefined) {
      nx = table()
      cur.map.set(names[i], nx)
    } else if (nx.t === 'array' && nx.aot) {
      nx = nx.items[nx.items.length - 1]
    } else if (nx.t !== 'table') {
      fail(`${names.slice(0, i + 1).join('.')} is not a table`)
    }
    cur = nx
  }
  return cur
}

