  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++ }
  get ch() { return this.s[this.i] }
  atEnd() { return this.i >= this.s.length }
  atComment() { return this.ch === '#' || this.ch === ';' }
  endOrComment() { this.ws(); return this.atEnd() || this.atComment() }

  quoted() {
    const q = this.ch
    this.i++
    let out = ''
    for (;;) {
      if (this.atEnd()) fail('unterminated string')
      const c = this.ch
      if (c === q) { this.i++; return out }
      if (q === "'" || c !== '\\') { out += c; this.i++; continue }
      this.i++
      if (this.atEnd()) fail('unterminated string')
      const e = this.ch
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (e in map) { out += map[e]; this.i++ } else if (e === 'u') {
        const h = this.s.slice(this.i + 1, this.i + 5)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 5
      } else fail(`invalid escape \\${String.fromCodePoint(this.s.codePointAt(this.i))}`)
    }
  }

