    const c = this.ch
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (!this.atEnd() && BARE.test(this.ch)) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted(onEnd) {
    const names = []
    this.ws()
    if (onEnd && this.atEnd()) fail(onEnd)
    names.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.ch === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else { this.i = save; return names }
    }
  }

  value() {
    this.ws()
    if (this.atEnd() || this.atComment() || this.ch === ',' || this.ch === ']' || this.ch === '}') fail('expected a value')
    const c = this.ch
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
