function assign(base, prefix, names, v) {
  const full = [...prefix, ...names]
  let cur = base
  for (let i = 0; i < names.length - 1; i++) {
    let nx = cur.map.get(names[i])
    if (nx === undefined) {
      nx = table()
      cur.map.set(names[i], nx)
    } else if (nx.t === 'array' && nx.aot) {
      nx = nx.items[nx.items.length - 1]
    } else if (nx.t !== 'table') {
      fail(`${full.slice(0, prefix.length + i + 1).join('.')} is not a table`)
    }
    cur = nx
  }
  const last = names[names.length - 1]
  if (cur.map.has(last)) fail(`key ${full.join('.')} is defined twice`)
  cur.map.set(last, v)
}

export function parseDocument(lines) {
  const root = table()
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const p = new LineParser(lines[n])
      p.ws()
      if (p.atEnd() || p.atComment()) continue
      if (p.ch === '[') {
        const dbl = p.s[p.i + 1] === '['
        p.i += dbl ? 2 : 1
        p.ws()
        const names = p.dotted()
        p.ws()
        const close = (dbl ? ']]' : ']')
        if (p.s.slice(p.i, p.i + close.length) !== close) fail('unterminated table header')
        p.i += close.length
        if (!p.endOrComment()) fail('trailing text after a table header')
        const path = names.join('.')
        const parent = walkTo(root, names, names.length - 1)
        const last = names[names.length - 1]
        const ex = parent.map.get(last)
        if (dbl) {
          if (ex === undefined) {
            const arr = { t: 'array', items: [], aot: true }
            parent.map.set(last, arr)
            cur = table()
            arr.items.push(cur)
          } else if (ex.t === 'array' && ex.aot) {
            cur = table()
            ex.items.push(cur)
          } else fail(`${path} is not an array of tables`)
        } else if (ex === undefined) {
          cur = table()
          cur.header = true
          parent.map.set(last, cur)
        } else if (ex.t !== 'table') {
          fail(`${path} is not a table`)
        } else {
          if (ex.header) fail(`table ${path} is defined twice`)
          ex.header = true
          cur = ex
        }
        curPath = names
        continue
      }
      const names = p.dotted()
      p.ws()
      if (p.ch !== '=') fail('expected key = value')
      p.i++
      const v = p.value()
      if (!p.endOrComment()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof Fail) { e.line = n + 1 }
      throw e
    }
  }
  return root
}
